/* ============================================================
   05c — ГОСПОДИН ЦВЕТОВ (LORD OF FLOWERS)
   Пользовательская МУЗЫКА атаки и войсклипы Flowery встроены в билд
   (base64), играются через ту же WebAudio-шину, что и прочие звуки
   (с учётом громкости SFX/музыки).
   ============================================================ */
const FLOWER_MUSIC_MP3 = 'data:audio/mpeg;base64,';

const FLOWER_VOICE_POWERS = 'data:audio/ogg;base64,';
const FLOWER_VOICE_LAST = 'data:audio/ogg;base64,';
const FLOWER_VOICE_HEH = 'data:audio/ogg;base64,';
const FLOWER_VOICE_1 = 'data:audio/ogg;base64,';
const FLOWER_VOICE_2 = 'data:audio/ogg;base64,';
const FLOWER_VOICE_3 = 'data:audio/ogg;base64,';
const FLOWER_VOICE_4 = 'data:audio/ogg;base64,';

const FLOWER_VOICE_LIST = [FLOWER_VOICE_1, FLOWER_VOICE_2, FLOWER_VOICE_3, FLOWER_VOICE_4, FLOWER_VOICE_HEH];

/* ЗАГЛУШКИ: реплики, файлы которых пользователь ещё не прислал. Как только
   пришлёт — достаточно вписать сюда base64 data-url, звук подхватится сам. */
const FLOWER_VOICE_OMEGA = (typeof FLOWER_V_OMEGA === 'string') ? FLOWER_V_OMEGA : '';
const FLOWER_VOICE_FALLING = (typeof FLOWER_V_FALLING === 'string') ? FLOWER_V_FALLING : '';
const FLOWER_VOICE_SLAM = (typeof FLOWER_V_LAST === 'string' && FLOWER_V_LAST) ? FLOWER_V_LAST : FLOWER_VOICE_LAST;
const FLOWER_VOICE_LOUD = [FLOWER_VOICE_HEH, FLOWER_VOICE_1, FLOWER_VOICE_2, FLOWER_VOICE_3, FLOWER_VOICE_4];
/* ---- наборы реплик ПО СОБЫТИЯМ (по канону Deltarune Chapter 5) ----
   Jarona 1–4 (ogg) — сама атака-рывок;
   «heh, it's my Jarona» / «my jarona» / «leaf it to me» — захват;
   «no no no» / «wow» / «and one more for the fans» / «take that» — убийство;
   «last jarona» — удар об землю; «omega flowery» — превращение;
   «I'm falling» — смерть; «with your powers combined» — заряд. */
const FLOWER_VOICE_CAPTURE_ALL = [FLOWER_V_MYJARONA, FLOWER_VOICE_HEH, FLOWER_V_LEAFIT, FLOWER_V_HEREICOME];
const FLOWER_VOICE_KILL_ALL = [FLOWER_V_NONONO, FLOWER_V_WOW, FLOWER_V_ONEMORE, FLOWER_V_TAKETHAT, FLOWER_V_FANS2, FLOWER_V_STINGUS];
const FLOWER_VOICE_TURN_ALL = [FLOWER_VOICE_1, FLOWER_VOICE_2, FLOWER_VOICE_3, FLOWER_VOICE_4, FLOWER_V_HEREICOME];
const FLOWER_VOICE_HIT_ALL = [FLOWER_V_TAKETHAT, FLOWER_V_HUH];
const FLOWER_VOICE_DASH_ALL = [FLOWER_V_HEREICOME, FLOWER_V_TAKETHAT, FLOWER_V_MYJARONA, FLOWER_V_JAORANGE];


/* ---- декодирование встроенных сэмплов (каждый — один раз) ---- */
function _flowerToU8(dataUrl) {
  const b = atob(dataUrl.split(',')[1]);
  const n = b.length, u8 = new Uint8Array(n);
  for (let i = 0; i < n; i++) u8[i] = b.charCodeAt(i);
  return u8;
}
Audio3D_SFX._flowerBufs = {};
Audio3D_SFX._flowerDecoding = {};
/* Возвращает AudioBuffer или null (декодирование асинхронное). */
Audio3D_SFX.flowerBuffer = function (key, dataUrl, onReady) {
  if (this._flowerBufs[key]) return this._flowerBufs[key];
  if (this._flowerDecoding[key] || !this.ctx) return null;
  this._flowerDecoding[key] = true;
  const self = this;
  try {
    const u8 = _flowerToU8(dataUrl);
    const done = (buf) => { self._flowerBufs[key] = buf; if (onReady) onReady(buf); };
    const p = this.ctx.decodeAudioData(u8.buffer, done, () => { });
    if (p && p.then) p.then(done).catch(() => { });
  } catch (e) { }
  return null;
};

/* МУЗЫКА АТАКИ: трек «Flower Man» играет поверх боя на канале музыки.
   Возвращает объект с огибающей громкости по времени (для синхронизации
   рывка: тихая часть — заряд, громкая — полёт), либо false. */
Audio3D_SFX.FLOWER_MUSIC_OUTRO = 0.55;   // затухание в конце трека, с
Audio3D_SFX.FLOWER_CHARGE = 4.0;         // длительность «заряда» под тихую часть, с
Audio3D_SFX.flowerMusic = function () {
  if (!this.ctx || this.muted || this.musicOff) return false;
  const self = this;
  const fire = () => {
    const buf = self.flowerBuffer('music', FLOWER_MUSIC_MP3, null);
    if (!buf) return false;
    if (self._flowerMusicSrc) { try { self._flowerMusicSrc.stop(); } catch (e) { } }
    const src = self.ctx.createBufferSource();
    src.buffer = buf;
    const g = self.ctx.createGain();
    g.gain.value = 0.9;
    // ---- огибающая громкости по 0.1с: ищем «более громкую» половину ----
    const info = self._flowerMusicAnalyze(buf);
    // ---- старт с указанного места (тихая часть), чтобы уложиться в рывок ----
    const startAt = info.startAt || 0;
    src.connect(g);
    g.connect(self.musicBus || self.sfx);
    src.onended = () => { if (self._flowerMusicSrc === src) self._flowerMusicSrc = null; };
    self._flowerMusicSrc = src;
    self._flowerMusicGain = g;
    self._flowerMusicStartCtx = self.ctx.currentTime;
    if (info.loudAt !== null && info.loudAt !== undefined) {
      src.start(0, startAt);
      self._flowerMusicStart = startAt;
    } else { src.start(); self._flowerMusicStart = 0; }
    info.startAt = self._flowerMusicStart;
    return info;                                   // объект-огибающая
  };
  let info = fire();
  if (info === false) {
    const iv = setInterval(() => { const r = fire(); if (r) { info = r; clearInterval(iv); } }, 60);
    setTimeout(() => clearInterval(iv), 6000);
    return { pending: true, loudAt: 0.55 };        // пока не декодировалось
  }
  return info;
};
/* Анализ трека: RMS по 0.1с, позиция «резкого подъёма» (начало громкой части),
   старт выбираем так, чтобы громкая часть наступила через ~задержку заряда. */
Audio3D_SFX._flowerMusicAnalyze = function (buf) {
  if (this._flowerMusicInfo) return this._flowerMusicInfo;
  const ch = buf.getChannelData(0), sr = buf.sampleRate, dur = buf.duration;
  const step = Math.round(sr * 0.1), n = Math.floor(ch.length / step);
  const env = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    let s = 0; const a = i * step, b = Math.min(a + step, ch.length);
    for (let j = a; j < b; j++) s += ch[j] * ch[j];
    env[i] = Math.sqrt(s / Math.max(1, b - a));
  }
  /* сглаживание */
  const sm = new Float32Array(n), W = 8;
  for (let i = 0; i < n; i++) {
    let s = 0, c = 0;
    for (let j = Math.max(0, i - W); j <= Math.min(n - 1, i + W); j++) { s += env[j]; c++; }
    sm[i] = s / c;
  }
  /* ищем самый сильный устойчивый подъём (переход тихо→громко) */
  let bestI = -1, bestScore = -1;
  for (let i = W * 2; i < n - W * 2; i++) {
    const before = (sm[i - 1] + sm[i - 2] + sm[i - 3]) / 3;
    const after = (sm[i] + sm[i + 1] + sm[i + 2]) / 3;
    const score = (after - before);
    if (after > before && score > bestScore) { bestScore = score; bestI = i; }
  }
  const loudAt = bestI > 0 ? bestI * 0.1 : null;
  /* ---- ОНСЕТЫ (удары/сильные доли) для синхронизации рывка с ритмом ---- */
  const onsets = [];
  const win = 6;
  for (let i = win; i < n - 1; i++) {
    const before = (env[i - 1] + env[i - 2] + env[i - 3]) / 3;
    if (env[i] > before * 1.35 + 0.02 && env[i] > 0.14) {
      const gap = (i - (onsets.length ? onsets[onsets.length - 1] : -99) * 10) * 0.1;
      if (gap >= 0.28) onsets.push(i * 0.1);
    }
  }
  /* старт: громкая часть должна наступить через CHARGE (заряд) секунд */
  const charge = this.FLOWER_CHARGE || 4.0;
  let startAt = 0;
  if (loudAt !== null) startAt = Math.max(startAt, Math.max(0, loudAt - charge));
  /* не выходим за пределы трека с учётом времени полёта */
  const flightMax = (this.FLOWER_FLIGHT_MAX || 6.0);
  const maxStart = Math.max(0, dur - charge - flightMax);
  if (startAt > maxStart) startAt = maxStart;
  this._flowerMusicInfo = { dur: dur, loudAt: loudAt, startAt: startAt, env: sm, envStep: 0.1, onsets: onsets };
  return this._flowerMusicInfo;
};
/* Удары (онсеты) трека, попадающие в окно полёта [fromAt, toAt] в секундах
   ОТ НАЧАЛА ТРЕКА. Используется, чтобы маневры рывка совпадали с ритмом. */
Audio3D_SFX.flowerMusicBeats = function (fromAt, toAt) {
  const info = this._flowerMusicInfo;
  if (!info || !info.onsets) return null;
  const out = [];
  for (let i = 0; i < info.onsets.length; i++) {
    const t = info.onsets[i];
    if (t >= fromAt && t <= toAt) out.push(t - (this._flowerMusicStart || 0));
  }
  return out;
};
/* Оставшееся время трека после текущего момента (для ограничения рывка). */
Audio3D_SFX.flowerMusicRemaining = function () {
  const info = this._flowerMusicInfo;
  if (!info) return null;
  const ctx = this.ctx;
  if (!ctx || !this._flowerMusicSrc) return null;
  const elapsed = (ctx.currentTime - (this._flowerMusicStartCtx || ctx.currentTime));
  const total = info.dur - (this._flowerMusicStart || 0) - this.FLOWER_MUSIC_OUTRO;
  return Math.max(1.5, total - elapsed);
};
Audio3D_SFX.flowerMusicStop = function () {
  if (this._flowerMusicSrc) { try { this._flowerMusicSrc.stop(); } catch (e) { } this._flowerMusicSrc = null; }
};

/* ГОЛОС: реплика Флауэра (непозиционная — кинематографично, у экрана).
   Возвращает длительность проигранной реплики в секундах (0 — если данных нет). */
Audio3D_SFX.flowerVoice = function (which, gain) {
  if (!this.ctx || this.muted) return 0;
  if (!which) return 0;                      // пустая заглушка — тишина
  const dataUrl = which;
  const key = 'v' + dataUrl.length;
  const self = this;
  const fire = () => {
    const buf = self.flowerBuffer(key, dataUrl, null);
    if (!buf) return false;
    const src = self.ctx.createBufferSource();
    src.buffer = buf;
    const g = self.ctx.createGain();
    g.gain.value = gain === undefined ? 0.95 : gain;
    src.connect(g); g.connect(self.sfx);
    src.start();
    return true;
  };
  if (!fire()) {
    const iv = setInterval(() => { if (fire()) clearInterval(iv); }, 40);
    setTimeout(() => clearInterval(iv), 4000);
  }
  const buf = this._flowerBufs[key];
  return buf ? buf.duration : 3.0;
};
